      "grounding": [
        {"node_id": "skp-intentions-121", "label": "Enforcing Parent Joint Enterprise Liability and Compulsory Insurance Across AI Deployments", "operationality": 5, "why": "primary strategy anchor — compulsory risk-pooling achieves the compensation goal without extinguishing claims; note the tail-risk underwriting vulnerability honestly"},
        {"node_id": "skp-intentions-139", "label": "Enforcing Runtime Observability Through Sectoral Safety Regulators", "operationality": 5, "why": "strategy — FDA predetermined change control plans, SEC circuit-breakers, and NHTSA defect investigations already do domain-calibrated versions of what the proposal's telemetry clause describes"},
        {"node_id": "skp-intentions-157", "label": "Surfacing Diffuse AI Harms Through a Public Enforcer Decoupled from Litigation", "operationality": 3, "why": "strategy — captures the proposal's legitimate insight that individual litigation under-surfaces diffuse harm, without paying for it in immunity"},
